package io.github.leocb.ls9.sysex;

import java.io.IOException;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Optional;
import io.github.leocb.ls9.internal.Csv;
import io.github.leocb.ls9.internal.Io;
import io.github.leocb.ls9.internal.Text;

/**
 * Lazy registry of all 1,033 parameter entries published in Yamaha's
 * {@code ParamChangeList_LS9.xls}. The CSV resource is generated by
 * {@code tools/generate_resources.py}.
 */
public final class Ls9ParameterRegistry {

    private static final String RESOURCE = "/io/github/leocb/ls9/ls9-parameters.csv";
    private static volatile Ls9ParameterRegistry instance;

    private final List<ParameterDefinition> all;
    private final Map<String, ParameterDefinition> byElementAndIndexName;
    private final Map<Long, ParameterDefinition> byElementAndIndex;

    private Ls9ParameterRegistry(List<ParameterDefinition> all) {
        this.all = Collections.unmodifiableList(new ArrayList<>(all));
        Map<String, ParameterDefinition> names = new LinkedHashMap<>();
        Map<Long, ParameterDefinition> numbers = new LinkedHashMap<>();
        for (ParameterDefinition d : all) {
            names.putIfAbsent(key(d.element(), d.indexName()), d);
            numbers.putIfAbsent(key(d.elementHex(), d.indexHex()), d);
        }
        this.byElementAndIndexName = Collections.unmodifiableMap(names);
        this.byElementAndIndex = Collections.unmodifiableMap(numbers);
    }

    public static Ls9ParameterRegistry get() {
        Ls9ParameterRegistry local = instance;
        if (local == null) {
            synchronized (Ls9ParameterRegistry.class) {
                local = instance;
                if (local == null) {
                    local = load();
                    instance = local;
                }
            }
        }
        return local;
    }

    private static Ls9ParameterRegistry load() {
        try (InputStream in = Ls9ParameterRegistry.class.getResourceAsStream(RESOURCE)) {
            if (in == null) {
                throw new IllegalStateException("missing resource " + RESOURCE);
            }
            String text = new String(Io.readAll(in), StandardCharsets.UTF_8);
            List<List<String>> rows = Csv.parse(text);
            List<ParameterDefinition> defs = new ArrayList<>(rows.size());
            for (int i = 1; i < rows.size(); i++) {
                List<String> r = rows.get(i);
                if (r.size() < 12 || r.get(0).trim().isEmpty()) {
                    continue;
                }
                defs.add(new ParameterDefinition(
                        r.get(0),
                        r.get(1),
                        Integer.decode(r.get(2)),
                        r.get(3),
                        Integer.decode(r.get(4)),
                        r.get(5),
                        r.get(6),
                        r.get(7),
                        parseIntOrZero(r.get(8)),
                        r.get(9),
                        parseIntOrZero(r.get(10)),
                        r.get(11)));
            }
            return new Ls9ParameterRegistry(defs);
        } catch (IOException e) {
            throw new IllegalStateException("cannot load " + RESOURCE, e);
        }
    }

    private static int parseIntOrZero(String s) {
        try {
            return (int) Double.parseDouble(s);
        } catch (RuntimeException e) {
            return 0;
        }
    }

    public List<ParameterDefinition> all() {
        return all;
    }

    public Optional<ParameterDefinition> find(String element, String indexName) {
        return Optional.ofNullable(byElementAndIndexName.get(key(element, indexName)));
    }

    public Optional<ParameterDefinition> find(int element, int index) {
        return Optional.ofNullable(byElementAndIndex.get(key(element, index)));
    }

    /** Case-insensitive substring search over element, index and comment. */
    public List<ParameterDefinition> search(String text) {
        String needle = text.toLowerCase(Locale.ROOT);
        List<ParameterDefinition> out = new ArrayList<>();
        for (ParameterDefinition d : all) {
            if (d.element().toLowerCase(Locale.ROOT).contains(needle)
                    || d.indexName().toLowerCase(Locale.ROOT).contains(needle)
                    || d.comment().toLowerCase(Locale.ROOT).contains(needle)) {
                out.add(d);
            }
        }
        return out;
    }

    private static String key(String a, String b) {
        return a + "\u0000" + b;
    }

    private static long key(int a, int b) {
        return ((long) a << 32) | (b & 0xFFFFFFFFL);
    }
}
